class Solution {
    private int[] counts;
    public List<Integer> countSmaller(int[] nums) {
        int n = nums.length;
        counts = new int[n];
        int[][] indexed = new int[n][2];
        for (int i = 0; i < n; i++) indexed[i] = new int[]{nums[i], i};
        mergeSort(indexed, 0, n - 1);
        List<Integer> result = new java.util.ArrayList<>();
        for (int c : counts) result.add(c);
        return result;
    }
    private void mergeSort(int[][] arr, int lo, int hi) {
        if (lo >= hi) return;
        int mid = lo + (hi - lo) / 2;
        mergeSort(arr, lo, mid);
        mergeSort(arr, mid + 1, hi);
        merge(arr, lo, mid, hi);
    }
    private void merge(int[][] arr, int lo, int mid, int hi) {
        int[][] temp = new int[hi - lo + 1][2];
        int i = lo, j = mid + 1, k = 0, rightCount = 0;
        while (i <= mid && j <= hi) {
            if (arr[j][0] < arr[i][0]) { rightCount++; temp[k++] = arr[j++]; }
            else { counts[arr[i][1]] += rightCount; temp[k++] = arr[i++]; }
        }
        while (i <= mid) { counts[arr[i][1]] += rightCount; temp[k++] = arr[i++]; }
        while (j <= hi) temp[k++] = arr[j++];
        System.arraycopy(temp, 0, arr, lo, temp.length);
    }
}

import java.util.*;

class Solution {
    private int[] tree;
    public List<Integer> countSmaller(int[] nums) {
        int n = nums.length;
        int[] sorted = nums.clone();
        Arrays.sort(sorted);
        Map<Integer, Integer> ranks = new HashMap<>();
        int rank = 1;
        for (int v : sorted) {
            if (!ranks.containsKey(v)) {
                ranks.put(v, rank++);
            }
        }
        tree = new int[rank + 1];
        Integer[] result = new Integer[n];
        for (int i = n - 1; i >= 0; i--) {
            int r = ranks.get(nums[i]);
            result[i] = query(r - 1);
            update(r, rank);
        }
        return Arrays.asList(result);
    }
    private void update(int i, int max) {
        for (; i <= max; i += i & (-i)) tree[i]++;
    }
    private int query(int i) {
        int sum = 0;
        for (; i > 0; i -= i & (-i)) sum += tree[i];
        return sum;
    }
}
